在 scripts/run-daily-tasks.mjs 中 boardLedger 读取和远端持久化校验之后、席位循环之前插入以下代码：

```js
  const currentRunKey = `${process.env.GITHUB_RUN_ID || "local"}:${process.env.GITHUB_RUN_ATTEMPT || "1"}`;
  if (boardLedger.run_key !== currentRunKey) {
    throw Error(`daily_reservation_run_key_mismatch: ledger=${boardLedger.run_key} current=${currentRunKey}`);
  }
  const mismatchSeats = Object.entries(boardLedger.seats || {})
    .filter(([, seat]) => seat.status === 'reserved' && seat.claim_receipt?.run_key && seat.claim_receipt.run_key !== currentRunKey)
    .map(([agent, seat]) => `${agent}:${seat.claim_receipt.run_key}`);
  if (mismatchSeats.length) {
    throw Error(`daily_reservation_seat_run_key_mismatch: ${mismatchSeats.join(',')}`);
  }
```

同时删除下方原有的 `const runKey=...` 定义，复用上述 currentRunKey 变量传入 runReservedSeat。
